exact_vertices=[[tuple(Fraction(x) for x in v) for v in o['vertices']] for o in geometry['objects']]
panels=[]
for index,obj in enumerate(geometry['objects']):
    vertices=exact_vertices[index]; triangles=obj['triangles']
    if len(vertices)!=4 or len(set(vertices))!=4 or len(triangles)!=2: continue
    normals=[cross(sub(vertices[t[1]],vertices[t[0]]),sub(vertices[t[2]],vertices[t[0]])) for t in triangles]
    if not dot(normals[0],normals[0]) or dot(normals[0],normals[1])<=0: continue
